112	\label{sec:picardJacobianWitness}
113	
114	\begin{theorem}[The Picard identity component is a Jacobian witness]\leanok
115	  \label{def:picardJacobianWitness}
116	  \uses{def:JacobianWitness, def:genus, thm:fga_pic_representability,
117	    thm:pic0_isAbelianVariety, thm:pic_zero_dimension_equals_genus,
118	    thm:albanese_universal_property_northstar}
119	  \lean{AlgebraicGeometry.picardJacobianWitness}
120	  The identity component \(\Pic^0_{C/k}\) carries a Jacobian witness for
121	  \(C\).
122	\end{theorem}
123	
124	\begin{proof}
125	  Representability of the relative Picard functor gives \(\Pic_{C/k}\).
126	  Its identity component is a group scheme; the structure theorem for the
127	  identity component of the Picard scheme makes it smooth, proper, and
128	  geometrically irreducible.  The tangent-space identification
129	  \[
130	    T_0\Pic^0_{C/k}\cong H^1(C,\mathcal O_C)
131	  \]
132	  gives relative dimension \(g(C)\).  Finally, the Abel--Jacobi morphism and
133	  its universal property give an Albanese structure for each \(P\in C(k)\).
134	  These data form the required witness.
135	\end{proof}
136	
137	\begin{theorem}[Existence of a Jacobian witness]\leanok
138	  \label{thm:nonempty_jacobianWitness}
139	  \uses{def:JacobianWitness, def:picardJacobianWitness}
140	  \lean{AlgebraicGeometry.nonempty_jacobianWitness}
141	  Every smooth proper geometrically irreducible curve has a Jacobian witness.

