cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 - <<'EOF'
import yaml,glob,os
items={}
for p in glob.glob('/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(p))
    items[d['id']]=d
kids={}
for i,d in items.items():
    par=(d.get('metadata') or {}).get('parent')
    if par: kids.setdefault(par,[]).append(i)
OPEN={'pending','active','blocked'}
print('total roadmap items',len(items))
# find disagreements
for i,d in sorted(items.items()):
    ch=kids.get(i,[])
    if not ch: continue
    st=d.get('status'); cs=[items[c].get('status') for c in ch]
    if st in OPEN and all(c in ('done','rejected') for c in cs):
        print('ALL-CHILDREN-DONE, PARENT OPEN:',i,st,'| children',len(ch),set(cs))
    if st=='done' and any(c in OPEN for c in cs):
        print('DONE PARENT, OPEN CHILDREN:',i,st,'| open kids',[c for c in ch if items[c]['status'] in OPEN])
EOF

